    v9_keys = v8_keys | {"queue"}
    # v10 在既有十二键末追加 capacities；十三键结构只可能为 v10。
    v10_keys = v9_keys | {"capacities"}
    # v11 在既有十三键末追加 lifetime；十四键结构只可能为 v11。
    v11_keys = v10_keys | {"lifetime"}
    if config_keys == v1_keys:
