        # INPUT。
        if list(value) != [
            "version", "backends", "vnodes", "limits", "overload",
            "sticky", "idle", "backpressure", "scheduler", "faults",
            "quotas", "queue", "capacities",
        ]:
            fail(EXIT_INPUT, "INPUT")
        version = 10
    elif config_keys == v11_keys:
