    if name == "ls":
        if keys != {"op", "scope", "id", "r", "b", "now"}:
            fail(EXIT_INPUT, "INPUT")
        scope = raw_op["scope"]
        if scope not in ("B", "C", "S"):
            fail(EXIT_INPUT, "INPUT")
