    current_export = export_config()
    candidate_export = export_normalized_config(config)
    changes = []
    for section in (
        "vnodes", "limits", "overload", "sticky", "idle",
        "backpressure", "scheduler", "faults", "quotas", "queue",
        "capacities", "lifetime",
    ):
