    # rev,now,kind,section,before,after，响应键序 op,events。重复
    # 查询逐字节相同；事件追加后不就地修改，逐项复制成全新结构。
    # O(A)，A≤64。
    results.append(
        {
            "op": "al",
            "events": [
                {
                    "rev": event["rev"],
                    "now": event["now"],
                    "kind": event["kind"],
