    after_digest = config_digest(new_snapshot)
    new_rev = next_rev
    next_rev += 1
    if len(commit_history) > 16:
        commit_history.pop(0)
    # cb 成功清除既有配置预约。
    reservation = None
    # 审计：成功并分配新 rev 时追加（仅留最近 64 条），section 恒
    # null；before 为回滚前指纹，after 为目标快照指纹。同一事件内
    # 固化段级差异（仅指纹，按顶层键序）。
    audit_events.append(
        {
            "rev": new_rev,

elif op[0] == "cu":
    # 单字段配置热加载：以当前 ce.config 规范化 version=11 导出为
