def checkpoint_digest(state):
    """对紧凑 UTF-8 编码的 {"version":1,"state":...} 取小写 SHA-256；
    返回 (hex 摘要, state 紧凑编码字节)。O(N)。"""
    envelope = {"version": CHECKPOINT_VERSION, "state": state}
    encoded = json.dumps(
        envelope, ensure_ascii=False, separators=(",", ":")
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest(), encoded

