        na_entry = None
        if al["na"] is not None:
            arr = cp_list(al["na"])
            if len(arr) != 9:
                fail(EXIT_INPUT, "INPUT")
            hi = si2(arr[0], 1, 10 ** 9)
            lo = si2(arr[1], 0, 10 ** 9 - 1)
