            nastate = enum(arr[3], ("N", "A"))
            run = ni(arr[4])
            naw = ti(arr[5])
            nasamples = ni(arr[6])
            napeak = ni(arr[7])
            cp_bool(arr[8])
            na_entry = {
                "hi": hi, "lo": lo, "n": n, "state": nastate,
                "run": run, "w": naw,
                "result": {
                    "op": "na", "id": backend_id, "w": naw,
