            "circuit": circuit,
            "drain": {
                "t": drain_t, "state": dstate, "start": dstart,
                "end": dend, "deadline": ddeadline, "forced": dforced,
            },
            "unavail_since": {
                "health": since_health, "drain": since_drain,
