        cp_bool(arr[10])
        wait_alerts[kind] = {
            "p": p, "hi": hi, "lo": lo, "n": n, "state": wstate,
            "run": run, "w": ww,
            "result": {
                "op": "wa", "kind": kind, "w": ww, "p": p,
                "state": wstate, "samples": samples_v,
