        pair_order.append(pair)
    check_pair_order(pair_order)

    # ---- 等待队列（FIFO）----
    wait_queue = OrderedDict()
    for wq in cp_list(root["wait_queue"]):
        item = o(wq, ("cid", "flow", "c", "s", "key", "cost", "now"))
