    if queue_cfg is not None and len(wait_queue) > queue_cfg[1]:
        cp_state_int()
    if queue_cfg is None and wait_queue:
        cp_state_int()

    # ---- 接纳容量覆盖（按后端加入序）----
    cap_overrides = {}
