    # ---- 提交历史（rev 升序，至多 16）与审计（至多 64）----
    def snapshot_config(value):
        objv = o(value, (
            "version", "backends", "vnodes", "limits", "overload",
            "sticky", "idle", "backpressure", "scheduler", "faults",
            "quotas", "queue", "capacities", "lifetime",
        ))
